spring:
  application:
    name: sofascore-local-lab
  config:
    import: "optional:file:.env[.properties]"
  profiles:
    default: local
  threads:
    virtual:
      enabled: true
  datasource:
    url: jdbc:postgresql://127.0.0.1:${POSTGRES_PORT:5432}/${POSTGRES_DB:sofascore_local_lab}
    username: ${POSTGRES_USER:sofascore_lab}
    password: ${POSTGRES_PASSWORD:}
    hikari:
      maximum-pool-size: 4
      minimum-idle: 1
      connection-timeout: 5000
      validation-timeout: 2000
  jpa:
    open-in-view: false
    hibernate:
      ddl-auto: none
    properties:
      hibernate:
        jdbc:
          time_zone: UTC
  flyway:
    enabled: true
    validate-migration-naming: true
  cache:
    type: caffeine
    cache-names:
      - endpointCatalog
      - providerResponses
    caffeine:
      spec: maximumSize=500,expireAfterWrite=30m
  thymeleaf:
    cache: true
  servlet:
    multipart:
      max-file-size: 6MB
      max-request-size: 32MB
      file-size-threshold: 32MB

server:
  address: 127.0.0.1
  port: 8087
  shutdown: graceful
  tomcat:
    max-part-count: 82
  servlet:
    session:
      cookie:
        http-only: true
        same-site: strict
  error:
    include-message: never
    include-stacktrace: never

management:
  endpoints:
    web:
      exposure:
        include: health,info,metrics
  endpoint:
    health:
      show-details: always
  info:
    env:
      enabled: true

info:
  app:
    name: SofaScore Local Lab
    version: 0.1.0-rc.1-SNAPSHOT
    phase: J8-BENCHMARK-VALIDATED
    status: EXPERIMENTAL_LOCAL_ONLY

sofascore:
  enabled: ${SOFASCORE_ENABLED:false}
  live:
    enabled: ${SOFASCORE_LIVE_ENABLED:false}
    docker-executable: ${SOFASCORE_LIVE_DOCKER_EXECUTABLE:}
    postgres-container: ${SOFASCORE_LIVE_POSTGRES_CONTAINER:betting-sofascore-local-lab-postgres}
    qualified-match-capacity: ${SOFASCORE_LIVE_QUALIFIED_MATCH_CAPACITY:1}
    qualification-sha256: ${SOFASCORE_LIVE_QUALIFICATION_SHA256:}
    request-envelope: ${SOFASCORE_LIVE_REQUEST_ENVELOPE:10s}
    processing-envelope: ${SOFASCORE_LIVE_PROCESSING_ENVELOPE:1s}
    grouped:
      qualification-sha256: ${SOFASCORE_LIVE_GROUPED_QUALIFICATION_SHA256:}
      endpoints:
        EVENT_DETAILS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_J4_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_J4_PROCESSING_ENVELOPE:1s}
        EVENT_INCIDENTS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_INCIDENTS_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_INCIDENTS_PROCESSING_ENVELOPE:1s}
        EVENT_STATISTICS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_STATISTICS_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_STATISTICS_PROCESSING_ENVELOPE:1s}
        EVENT_LINEUPS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_LINEUPS_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_LINEUPS_PROCESSING_ENVELOPE:1s}
    grouped-v5:
      qualification-sha256: ${SOFASCORE_LIVE_GROUPED_V5_QUALIFICATION_SHA256:}
      endpoints:
        EVENT_DETAILS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_V5_J4_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_V5_J4_PROCESSING_ENVELOPE:1s}
        EVENT_INCIDENTS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_V5_INCIDENTS_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_V5_INCIDENTS_PROCESSING_ENVELOPE:1s}
        EVENT_STATISTICS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_V5_STATISTICS_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_V5_STATISTICS_PROCESSING_ENVELOPE:1s}
        EVENT_LINEUPS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_V5_LINEUPS_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_V5_LINEUPS_PROCESSING_ENVELOPE:1s}
    grouped-v6:
      qualification-sha256: ${SOFASCORE_LIVE_GROUPED_V6_QUALIFICATION_SHA256:}
      endpoints:
        EVENT_DETAILS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_V6_J4_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_V6_J4_PROCESSING_ENVELOPE:1s}
        EVENT_INCIDENTS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_V6_INCIDENTS_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_V6_INCIDENTS_PROCESSING_ENVELOPE:1s}
        EVENT_STATISTICS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_V6_STATISTICS_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_V6_STATISTICS_PROCESSING_ENVELOPE:1s}
        EVENT_LINEUPS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_V6_LINEUPS_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_V6_LINEUPS_PROCESSING_ENVELOPE:1s}
    grouped-v7:
      qualification-sha256: ${SOFASCORE_LIVE_GROUPED_V7_QUALIFICATION_SHA256:}
      endpoints:
        EVENT_DETAILS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_V7_J4_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_V7_J4_PROCESSING_ENVELOPE:1s}
        EVENT_INCIDENTS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_V7_INCIDENTS_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_V7_INCIDENTS_PROCESSING_ENVELOPE:1s}
        EVENT_STATISTICS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_V7_STATISTICS_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_V7_STATISTICS_PROCESSING_ENVELOPE:1s}
        EVENT_LINEUPS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_V7_LINEUPS_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_V7_LINEUPS_PROCESSING_ENVELOPE:1s}
    grouped-v8:
      qualification-sha256: ${SOFASCORE_LIVE_GROUPED_V8_QUALIFICATION_SHA256:}
      endpoints:
        EVENT_DETAILS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_V8_J4_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_V8_J4_PROCESSING_ENVELOPE:1s}
        EVENT_INCIDENTS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_V8_INCIDENTS_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_V8_INCIDENTS_PROCESSING_ENVELOPE:1s}
        EVENT_STATISTICS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_V8_STATISTICS_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_V8_STATISTICS_PROCESSING_ENVELOPE:1s}
        EVENT_LINEUPS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_V8_LINEUPS_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_V8_LINEUPS_PROCESSING_ENVELOPE:1s}
    # V9 is independently qualified. It must not inherit a V8 proof merely
    # because its J4 facts can suppress optional J5 calls at runtime.
    grouped-v9:
      qualification-sha256: ${SOFASCORE_LIVE_GROUPED_V9_QUALIFICATION_SHA256:}
      endpoints:
        EVENT_DETAILS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_V9_J4_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_V9_J4_PROCESSING_ENVELOPE:1s}
        EVENT_INCIDENTS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_V9_INCIDENTS_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_V9_INCIDENTS_PROCESSING_ENVELOPE:1s}
        EVENT_STATISTICS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_V9_STATISTICS_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_V9_STATISTICS_PROCESSING_ENVELOPE:1s}
        EVENT_LINEUPS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_V9_LINEUPS_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_V9_LINEUPS_PROCESSING_ENVELOPE:1s}
    # V10 owns an independent qualification and a stricter local pressure profile.
    # Its scheduler shape remains the immutable V9 state machine.
    grouped-v10:
      qualification-sha256: ${SOFASCORE_LIVE_GROUPED_V10_QUALIFICATION_SHA256:}
      endpoints:
        EVENT_DETAILS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_V10_J4_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_V10_J4_PROCESSING_ENVELOPE:1s}
        EVENT_INCIDENTS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_V10_INCIDENTS_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_V10_INCIDENTS_PROCESSING_ENVELOPE:1s}
        EVENT_STATISTICS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_V10_STATISTICS_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_V10_STATISTICS_PROCESSING_ENVELOPE:1s}
        EVENT_LINEUPS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_V10_LINEUPS_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_V10_LINEUPS_PROCESSING_ENVELOPE:1s}
    # V11 requires its own worker/context-pause qualification; V10 evidence is not reused.
    grouped-v11:
      qualification-sha256: ${SOFASCORE_LIVE_GROUPED_V11_QUALIFICATION_SHA256:}
      endpoints:
        EVENT_DETAILS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_V11_J4_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_V11_J4_PROCESSING_ENVELOPE:1s}
        EVENT_INCIDENTS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_V11_INCIDENTS_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_V11_INCIDENTS_PROCESSING_ENVELOPE:1s}
        EVENT_STATISTICS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_V11_STATISTICS_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_V11_STATISTICS_PROCESSING_ENVELOPE:1s}
        EVENT_LINEUPS:
          request-envelope: ${SOFASCORE_LIVE_GROUPED_V11_LINEUPS_REQUEST_ENVELOPE:10s}
          processing-envelope: ${SOFASCORE_LIVE_GROUPED_V11_LINEUPS_PROCESSING_ENVELOPE:1s}
  playwright:
    enabled: ${SOFASCORE_PLAYWRIGHT_ENABLED:false}
    worker-jar: ${SOFASCORE_PLAYWRIGHT_WORKER_JAR:}
    maximum-heap-mib: ${SOFASCORE_PLAYWRIGHT_MAXIMUM_HEAP_MIB:192}
    startup-timeout: ${SOFASCORE_PLAYWRIGHT_STARTUP_TIMEOUT:30s}
    request-timeout: ${SOFASCORE_PLAYWRIGHT_REQUEST_TIMEOUT:10s}
    graceful-close-timeout: ${SOFASCORE_PLAYWRIGHT_GRACEFUL_CLOSE_TIMEOUT:5s}
    loopback-qualification: ${SOFASCORE_PLAYWRIGHT_LOOPBACK_QUALIFICATION:false}
    loopback-origin: ${SOFASCORE_PLAYWRIGHT_LOOPBACK_ORIGIN:}
  j3:
    runtime-enabled: ${SOFASCORE_J3_RUNTIME_ENABLED:true}
  j3-qualification-enabled: ${SOFASCORE_J3_QUALIFICATION_ENABLED:false}
  j4-event-details-qualification-enabled: ${SOFASCORE_J4_EVENT_DETAILS_QUALIFICATION_ENABLED:false}
  j4-event-details-phase2-enabled: ${SOFASCORE_J4_EVENT_DETAILS_PHASE2_ENABLED:false}
  j5-event-data-qualification-enabled: ${SOFASCORE_J5_EVENT_DATA_QUALIFICATION_ENABLED:false}
  tournament-event-discovery-enabled: ${SOFASCORE_TOURNAMENT_EVENT_DISCOVERY_ENABLED:false}
  base-url: ${SOFASCORE_BASE_URL:}
  maximum-concurrency: 1
  minimum-delay: 3s
  connect-timeout: 5s
  read-timeout: 10s
  automatic-refresh-enabled: false
  live-polling-enabled: false
  store-raw-payloads: true
  raw-payload-retention-days: 30
  export-directory: ${SOFASCORE_EXPORT_DIR:./exports}
  allowed-endpoints: ${SOFASCORE_ALLOWED_ENDPOINTS:}

optional-integration:
  enabled: false
  execution-mode: DISABLED
  remote-delivery-authorized: false
  official-permission-status: NOT_EVIDENCED
  receiver-qualification: NOT_QUALIFIED
  sender-qualification: NOT_QUALIFIED
  receiver-origin: ""
  loopback-qualification: false
  loopback-origin: ""
  maximum-concurrency: 1
  maximum-payload-bytes: 5242880
  maximum-acknowledgement-bytes: 16384
  protocol-version: "1.0"
  connect-timeout: 5s
  request-timeout: 10s
  automatic-retry-enabled: false
  mtls:
    required: true
    key-store-type: Windows-MY
    client-certificate-sha256: ""
  provider-owner-go:
    go-id: ""
    owner-go-document-sha256: ""

logging:
  level:
    root: INFO
    com.bettingproject.sofascorelocal: INFO
  pattern:
    console: "%d{yyyy-MM-dd'T'HH:mm:ss.SSSXXX} %-5level [%thread] %logger{36} - %msg%n"

  1: [CmdletBinding()]
  2: param(
  3:     [switch]$WithIntegrationTests
  4: )
  5: 
  6: $ErrorActionPreference = 'Stop'
  7: Set-StrictMode -Version 2.0
  8: 
  9: $repositoryRoot = Split-Path -Parent $PSScriptRoot
 10: if ($WithIntegrationTests) {
 11:     & (Join-Path $PSScriptRoot 'Preflight-Local.ps1')
 12: }
 13: else {
 14:     & (Join-Path $PSScriptRoot 'Preflight-Local.ps1') -SkipDocker -SkipEnvironmentFile
 15: }
 16: 
 17: $sourceRoot = Join-Path $repositoryRoot 'src\main'
 18: $sourceFiles = Get-ChildItem -LiteralPath $sourceRoot -Recurse -File |
 19:     Where-Object { $_.Extension -in @('.java', '.yml', '.yaml', '.properties') }
 20: $forbiddenPatterns = @(
 21:     'https?://[^\s"'']*sofascore',
 22:     'api\.sofascore',
 23:     'flaresolverr',
 24:     'localhost:8191',
 25:     '\bProxySelector\b',
 26:     '\borg\.openqa\.selenium\b',
 27:     '\bcom\.microsoft\.playwright\b',
 28:     '\bWebClient\s*\.(?:builder|create)\b'
 29: )
 30: $approvedProviderOriginDeclarations = @(
 31:     (Join-Path $sourceRoot `
 32:         'java\com\bettingproject\sofascorelocal\domain\provider\ScheduledEventsProviderPageRequest.java'),
 33:     (Join-Path $sourceRoot `
 34:         'java\com\bettingproject\sofascorelocal\domain\provider\EventDetailsProviderRequest.java'),
 35:     (Join-Path $sourceRoot `
 36:         'java\com\bettingproject\sofascorelocal\domain\provider\TournamentScheduledEventsProviderRequest.java')
 37: )
 38: $approvedProviderOriginLine =
 39:     'public static final String EXPECTED_ORIGIN = "https://www.sofascore.com";'
 40: 
 41: $violations = @()
 42: foreach ($pattern in $forbiddenPatterns) {
 43:     $matches = $sourceFiles |
 44:         Select-String -Pattern $pattern -CaseSensitive:$false
 45:     if ($pattern -eq $forbiddenPatterns[0]) {
 46:         $matches = $matches | Where-Object {
 47:             -not ($_.Path -in $approvedProviderOriginDeclarations -and
 48:                 $_.Line.Trim() -ceq $approvedProviderOriginLine)
 49:         }
 50:     }
 51:     if ($matches) {
 52:         $violations += $matches
 53:     }
 54: }
 55: 
 56: $approvedRestClientConstructions = @(
 57:     (Join-Path $sourceRoot `
 58:         'java\com\bettingproject\sofascorelocal\adapter\sofascore\transport\LoopbackScheduledEventsRestTransport.java')
 59: )
 60: $restClientConstructions = $sourceFiles |
 61:     Select-String -Pattern '\bRestClient\s*\.(?:builder|create)\b' -CaseSensitive:$false |
 62:     Where-Object { $_.Path -notin $approvedRestClientConstructions }
 63: if ($restClientConstructions) {
 64:     $violations += $restClientConstructions
 65: }
 66: 
 67: $removedJ3RestTransports = @(
 68:     (Join-Path $sourceRoot `
 69:         'java\com\bettingproject\sofascorelocal\adapter\sofascore\transport\ProviderScheduledEventsRestTransport.java'),
 70:     (Join-Path $sourceRoot `
 71:         'java\com\bettingproject\sofascorelocal\adapter\sofascore\transport\ProviderTournamentScheduledEventsRestTransport.java')
 72: )
 73: foreach ($removedTransport in $removedJ3RestTransports) {
 74:     if (Test-Path -LiteralPath $removedTransport) {
 75:         throw "Retired J3 RestClient transport is present: $removedTransport"
 76:     }
 77: }
 78: 
 79: $requiredJ3PlaywrightTransports = @(
 80:     (Join-Path $sourceRoot `
 81:         'java\com\bettingproject\sofascorelocal\adapter\sofascore\transport\ProviderScheduledEventsPlaywrightTransport.java'),
 82:     (Join-Path $sourceRoot `
 83:         'java\com\bettingproject\sofascorelocal\adapter\sofascore\transport\ProviderTournamentScheduledEventsPlaywrightTransport.java')
 84: )
 85: foreach ($requiredTransport in $requiredJ3PlaywrightTransports) {
 86:     if (-not (Test-Path -LiteralPath $requiredTransport)) {
 87:         throw "Required J3 Playwright transport is absent: $requiredTransport"
 88:     }
 89: }
 90: 
 91: $removedJ4RestTransport = Join-Path $sourceRoot `
 92:     'java\com\bettingproject\sofascorelocal\adapter\sofascore\transport\ProviderEventDetailsRestTransport.java'
 93: if (Test-Path -LiteralPath $removedJ4RestTransport) {
 94:     throw "Retired J4 RestClient transport is present: $removedJ4RestTransport"
 95: }
 96: 
 97: $requiredJ4PlaywrightTransport = Join-Path $sourceRoot `
 98:     'java\com\bettingproject\sofascorelocal\adapter\sofascore\transport\ProviderEventDetailsPlaywrightTransport.java'
 99: if (-not (Test-Path -LiteralPath $requiredJ4PlaywrightTransport)) {
100:     throw "Required J4 Playwright transport is absent: $requiredJ4PlaywrightTransport"
101: }
102: 
103: $removedJ5RestTransport = Join-Path $sourceRoot `
104:     'java\com\bettingproject\sofascorelocal\adapter\sofascore\transport\ProviderJ5EventDataRestTransport.java'
105: if (Test-Path -LiteralPath $removedJ5RestTransport) {
106:     throw "Retired J5 RestClient transport is present: $removedJ5RestTransport"
107: }
108: 
109: $requiredJ5PlaywrightTransport = Join-Path $sourceRoot `
110:     'java\com\bettingproject\sofascorelocal\adapter\sofascore\transport\ProviderJ5EventDataPlaywrightTransport.java'
111: if (-not (Test-Path -LiteralPath $requiredJ5PlaywrightTransport)) {
112:     throw "Required J5 Playwright transport is absent: $requiredJ5PlaywrightTransport"
113: }
114: 
115: $playwrightSourceRoot = Join-Path $repositoryRoot 'src\provider-playwright'
116: $playwrightSourceFiles = Get-ChildItem -LiteralPath $playwrightSourceRoot -Recurse -File |
117:     Where-Object { $_.Extension -eq '.java' }
118: $forbiddenPlaywrightPatterns = @(
119:     'flaresolverr',
120:     'localhost:8191',
121:     '\.setProxy\s*\(',
122:     '--proxy',
123:     '\.setUserAgent\s*\(',
124:     '\bstorageState\b',
125:     '\brecordHar',
126:     '\brecordVideo',
127:     '\.screenshot\s*\(',
128:     '\bconnectOverCDP\b',
129:     '\bpage\.content\s*\(',
130:     '\bresponse\.text\s*\('
131: )
132: foreach ($pattern in $forbiddenPlaywrightPatterns) {
133:     $matches = $playwrightSourceFiles |
134:         Select-String -Pattern $pattern -CaseSensitive:$false
135:     if ($matches) {
136:         $violations += $matches
137:     }
138: }
139: if ($violations.Count -gt 0) {
140:     $violations | ForEach-Object { Write-Error ($_.ToString()) }
141:     throw 'J3/J4/J5 source guardrail scan failed'
142: }
143: 
144: Push-Location $repositoryRoot
145: try {
146:     & .\mvnw.cmd -DskipITs clean verify
147:     if ($LASTEXITCODE -ne 0) {
148:         throw 'Standard Maven verification failed'
149:     }
150: 
151:     if ($WithIntegrationTests) {
152:         & .\mvnw.cmd -Pintegration-tests verify
153:         if ($LASTEXITCODE -ne 0) {
154:             throw 'Integration tests failed'
155:         }
156:     }
157: }
158: finally {
159:     Pop-Location
160: }
161: 
162: Write-Host 'VERIFY_RESULT=PASS'
163: Write-Host "INTEGRATION_TESTS_EXECUTED=$WithIntegrationTests"
164: Write-Host 'SOFASCORE_NETWORK_CALLS_EXECUTED=NO'

  1: package com.bettingproject.sofascorelocal.application.network;
  2: 
  3: import com.bettingproject.sofascorelocal.adapter.sofascore.SofascoreEndpointCatalog;
  4: import com.bettingproject.sofascorelocal.adapter.sofascore.scheduledevents.*;
  5: import com.bettingproject.sofascorelocal.adapter.sofascore.transport.ScheduledEventsTransportException;
  6: import com.bettingproject.sofascorelocal.domain.benchmark.*;
  7: import com.bettingproject.sofascorelocal.domain.provider.*;
  8: import com.bettingproject.sofascorelocal.domain.scheduledevents.J3AutomationData.Order;
