1318:         output.writeByte(j3PauseCapable?START_WITH_J3_PAUSE:START);
1319:         output.flush();
1320:         int frame = input.readUnsignedByte();
1321:         if (frame == FAILURE) {
1322:             throw workerFailure(input.readUTF());
1323:         }
1324:         if (frame != READY) {
1325:             throw new PlaywrightProviderException(
1326:                     PlaywrightProviderFailure.PROTOCOL_ERROR);
1327:         }
1328:     }
