 183:     private void awaitReservation(UUID dispatchId, PlaywrightDispatchAdmission admission, DepartureProfile departureProfile) {
 184:         while(true) {
 185:             admission.check(); requireOpen();
 186:             // Preserve the legacy method path for pre-V8 callers. This keeps their durable
 187:             // contract unchanged while V8 explicitly selects its faster local envelope.
 188:             var decision=departureProfile==DepartureProfile.LEGACY_V1
 189:                     ? store.tryReserveDeparture(dispatchId,clock.instant())
 190:                     : store.tryReserveDeparture(dispatchId,departureProfile,clock.instant());
 191:             if(decision.allowed()) return;
 192:             if(decision.reason()!=DepartureReason.RATE_LIMITED && decision.reason()!=DepartureReason.POST_EXCHANGE_FENCE)
 193:                 throw new IllegalStateException(decision.reason()==DepartureReason.PROVIDER_SUSPENDED
 194:                         ? "PROVIDER_SUSPENDED" : decision.reason()==DepartureReason.DEPARTURE_UNRESOLVED
 195:                         ? "PROVIDER_DEPARTURE_UNRESOLVED" : "PROVIDER_CLOCK_REGRESSION");
 196:             Instant until=decision.nextAllowedAt();
 197:             while(clock.instant().isBefore(until)) {
 198:                 admission.check();
 199:                 if(pendingRefusal.get()!=null) throw new IllegalStateException("PROVIDER_SUSPENDED");
 200:                 Duration remaining=Duration.between(clock.instant(),until);
 201:                 if(remaining.isNegative() || remaining.isZero()) break;
 202:                 try { pause.sleep(remaining.compareTo(Duration.ofMillis(50))>0?Duration.ofMillis(50):remaining); }
 203:                 catch(InterruptedException interrupted) {
 204:                     Thread.currentThread().interrupt(); throw new PlaywrightDispatchCancelledException();
 205:                 }
 206:             }
 207:         }
 208:     }
