 210:     private void observeRefusal(PlaywrightTransportDiagnostic d, UUID dispatchId, UUID campaignId,
 211:                                AtomicReference<Refusal> observed) {
 212:         if(d==null || d.httpStatus()==null || (d.httpStatus()!=403 && d.httpStatus()!=429)) return;
 213:         Refusal evidence=new Refusal(dispatchId,campaignId,d.httpStatus(),
 214:                 d.headersReceivedAt()==null?clock.instant():d.headersReceivedAt(),d.retryAfterNotBefore());
 215:         if(observed.compareAndSet(null,evidence)) persistRefusal(evidence);
